<?php
require_once __DIR__.'/includes/auth.php'; require_role(['administrador','enrutador']);
$pdo=db(); $date=$_GET['fecha']??date('Y-m-d'); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)) $date=date('Y-m-d');
$st=$pdo->prepare("SELECT s.id_solicitud,s.nombres,s.apellidos,s.barrio,s.comuna,s.direccion,s.celular,s.fecha_registro,p.nombre AS punto,u.nombres AS operador FROM solicitudes s JOIN puntos_atencion p ON p.id_punto=s.id_punto JOIN usuarios u ON u.id_usuario=s.id_usuario WHERE DATE(s.fecha_registro)=? ORDER BY s.fecha_registro ASC");$st->execute([$date]);$rows=$st->fetchAll();
$pageTitle='Bitácora diaria';require __DIR__.'/includes/header.php';
?>
<div class="mb-4"><div class="eyebrow">PERFIL ENRUTADOR</div><h1 class="page-title">Bitácora diaria de solicitudes</h1><p class="text-secondary">Consolidado de solicitudes generadas en todos los puntos de atención.</p></div><div class="content-card"><form class="d-flex flex-wrap align-items-end gap-2 mb-4"><div><label class="form-label">Fecha de consulta</label><input class="form-control" type="date" name="fecha" value="<?= e($date) ?>"></div><button class="btn btn-primary">Consultar</button><a class="btn btn-light" href="bitacora.php">Hoy</a></form><div class="d-flex flex-wrap gap-3 mb-3"><div class="summary-chip"><b><?= count($rows) ?></b><span>solicitudes</span></div><div class="summary-chip"><b><?= e(date('d/m/Y',strtotime($date))) ?></b><span>fecha consultada</span></div></div><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Hora</th><th>Código</th><th>Solicitante</th><th>Dirección</th><th>Barrio / comuna</th><th>Punto de atención</th><th>Registró</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="fw-semibold"><?= e(date('H:i:s',strtotime($r['fecha_registro']))) ?></td><td>#<?= (int)$r['id_solicitud'] ?></td><td><?= e($r['nombres'].' '.$r['apellidos']) ?><br><small class="text-secondary"><?= e($r['celular']) ?></small></td><td><?= e($r['direccion']) ?></td><td><?= e($r['barrio'].' · '.$r['comuna']) ?></td><td><?= e($r['punto']) ?></td><td><?= e($r['operador']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="text-center text-secondary py-4">No hay solicitudes para esta fecha.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
